css:
.dcs { font-family: Arial, sans-serif; font-size: 12px; color: #000; }
.dcs-title { text-align: center; font-size: 18px; font-weight: bold; background: #f2f2f2; padding: 8px; margin-bottom: 10px; }
.dcs-title span { display: block; font-size: 13px; direction: rtl; }
.dcs table { width: 100%; border-collapse: collapse; margin-bottom: 10px; }
.dcs-meta td { border: 1px solid #ccc; padding: 5px 6px; }
.dcs-meta td:nth-child(odd) { font-weight: bold; background: #fafafa; width: 15%; }
.dcs-lines td { padding: 5px 6px; border-bottom: 1px solid #eee; }
.dcs-lines td:last-child, .dcs-count td:last-child { text-align: right; }
.dcs-lines tr.strong td { font-weight: bold; border-top: 1px solid #000; }
.dcs-lines tr.short td { color: #c00; }
.dcs-lines tr.muted td { color: #777; }
.dcs-count th, .dcs-count td { border: 1px solid #000; padding: 4px 6px; }
.dcs-count th { background: #eaeaea; }
.dcs-sign td { width: 50%; padding-top: 40px; text-align: center; border-top: none; }
.dcs-sign td::before { content: ""; display: block; border-top: 1px solid #000; margin: 0 30px 4px; }

html:
{% set cur = frappe.db.get_single_value("Global Settings", "default_company") and frappe.db.get_value("Company", frappe.db.get_single_value("Global Settings", "default_company"), "default_currency") or "AED" %}
{% macro money(v) %}{{ frappe.utils.fmt_money(v or 0, currency=cur) }}{% endmacro %}
<div class="dcs">
  <div class="dcs-title">DAY CLOSE<span>إغلاق اليوم</span></div>

  <table class="dcs-meta">
    <tr><td>Session</td><td>{{ doc.name }}</td><td>Status</td><td>{{ doc.status }}</td></tr>
    <tr><td>Counter</td><td>{{ doc.counter }}{% if doc.counter_device %} · {{ doc.counter_device }}{% endif %}</td>
        <td>Cashier</td><td>{{ frappe.db.get_value("User", doc.cashier, "full_name") or doc.cashier }}</td></tr>
    <tr><td>Opened</td><td>{{ frappe.utils.format_datetime(doc.opened_on) if doc.opened_on else "" }}</td>
        <td>Closed</td><td>{{ frappe.utils.format_datetime(doc.closed_on) if doc.closed_on else "" }}</td></tr>
  </table>

  <table class="dcs-lines">
    {% if doc.previous_session %}
    <tr class="muted"><td>Previous close ({{ doc.previous_session }})</td><td>{{ money(doc.previous_closing_cash) }}</td></tr>
    {% endif %}
    <tr><td>Opening Float</td><td>{{ money(doc.opening_float) }}</td></tr>
    <tr><td>+ Cash Sales</td><td>{{ money(doc.cash_sales) }}</td></tr>
    <tr><td>+ Cash Receipts (Credit Collections)</td><td>{{ money(doc.cash_receipts) }}</td></tr>
    <tr><td>− Cash Refunds</td><td>{{ money(doc.cash_refunds) }}</td></tr>
    <tr><td>− Cash Paid Out</td><td>{{ money(doc.cash_paid_out) }}</td></tr>
    <tr><td>− Expenditure</td><td>{{ money(doc.cash_expenditure) }}</td></tr>
    <tr class="strong"><td>Expected Cash</td><td>{{ money(doc.expected_cash) }}</td></tr>
    <tr class="strong"><td>Counted Cash</td><td>{{ money(doc.counted_cash) }}</td></tr>
    <tr class="strong {{ 'short' if (doc.difference or 0) < 0 else '' }}"><td>Difference</td><td>{{ money(doc.difference) }}</td></tr>
  </table>

  {% if doc.opening_denominations %}
  <table class="dcs-count">
    <thead><tr><th>Opening Count</th><th>Count</th><th>Amount</th></tr></thead>
    <tbody>
    {% for row in doc.opening_denominations %}
      <tr><td>{{ row.denomination }}</td><td>{{ row.count }}</td><td>{{ money(row.amount) }}</td></tr>
    {% endfor %}
    </tbody>
  </table>
  {% endif %}
  {% if doc.opening_remarks %}<p><b>Opening remarks:</b> {{ doc.opening_remarks }}</p>{% endif %}

  {% if doc.denominations %}
  <table class="dcs-count">
    <thead><tr><th>Closing Count</th><th>Count</th><th>Amount</th></tr></thead>
    <tbody>
    {% for row in doc.denominations %}
      <tr><td>{{ row.denomination }}</td><td>{{ row.count }}</td><td>{{ money(row.amount) }}</td></tr>
    {% endfor %}
    </tbody>
  </table>
  {% endif %}

  {% if doc.close_remarks %}<p><b>Remarks:</b> {{ doc.close_remarks }}</p>{% endif %}
  {% if doc.closed_by and doc.closed_by != doc.cashier %}<p><b>Closed by supervisor:</b> {{ frappe.db.get_value("User", doc.closed_by, "full_name") or doc.closed_by }}</p>{% endif %}
  {% if doc.approved_by %}<p><b>Difference approved by:</b> {{ frappe.db.get_value("User", doc.approved_by, "full_name") or doc.approved_by }}</p>{% endif %}

  <table class="dcs-sign">
    <tr><td>Cashier</td><td>Supervisor</td></tr>
  </table>
</div>
